#[ConfigEntityType(
  id: 'commerce_referral_type',
  label: new TranslatableMarkup('Referral type'),
  label_collection: new TranslatableMarkup('Referral types'),
  config_prefix: 'commerce_referral_type',
  entity_keys: [
    'id' => 'id',
    'label' => 'label',
    'uuid' => 'uuid',
  ],
  handlers: [
    'list_builder' => ReferralTypeListBuilder::class,
    'form' => [
      'add' => ReferralTypeForm::class,
      'edit' => ReferralTypeForm::class,
      'delete' => EntityDeleteForm::class,
    ],
    'route_provider' => [
      'html' => AdminHtmlRouteProvider::class,
    ],
  ],
  links: [
    'add-form' => '/admin/commerce/config/referral-types/add',
    'edit-form' => '/admin/commerce/config/referral-types/{commerce_referral_type}',
    'delete-form' => '/admin/commerce/config/referral-types/{commerce_referral_type}/delete',
    'collection' => '/admin/commerce/config/referral-types',
  ],
  admin_permission: 'administer referral types',
  bundle_of: 'commerce_referral',
  config_export: [
    'id',
    'label',
    'referral_promotion',
    'kickback_promotion',
    'conditions',
    'condition_operator',
  ],
)]
class ReferralType extends ConfigEntityBundleBase {

  /**
   * The machine name of the bundle.
   *
   * @var string
   */
  protected string $id;

  /**
   * The human-readable label of the bundle.
   *
   * @var string
   */
  protected string $label;

  /**
   * The promotion ID used for the referee discount.
   *
   * @var string
   */
  protected string $referral_promotion;

  /**
   * The promotion ID used for the referrer kickback.
   *
   * @var string
   */
  protected string $kickback_promotion;

  /**
   * The conditions.
   *
   * @var array<array<string, mixed>>
   */
  protected array $conditions = [];

  /**
   * The condition operator.
   *
   * @var string
   */
  protected string $condition_operator = 'AND';

  /**
   * Gets the referral promotion ID.
   */
  public function getReferralPromotionId(): ?string {
    // Use config entity getter to avoid accessing an uninitialized property
    // during entity creation (add form).
    $value = $this->get('referral_promotion');

    // If the value is not a string or null, return null.
    if (!is_string($value)) {
      return NULL;
    }

    return $value;
  }

  /**
   * Gets the kickback promotion ID.
   */
  public function getKickbackPromotionId(): ?string {
    $value = $this->get('kickback_promotion');

    // If the value is not a string or null, return null.
    if (!is_string($value)) {
      return NULL;
    }

    return $value;
  }

  /**
   * Gets the conditions.
   *
   * @return \Drupal\commerce\Plugin\Commerce\Condition\ConditionInterface[]
   *   The conditions.
   */
  public function getConditions(): array {
    $conditions = [];
    $plugin_manager = \Drupal::service('plugin.manager.commerce_condition');

    foreach ($this->conditions as $condition) {
      if (isset($condition['plugin']) && is_string($condition['plugin']) && isset($condition['configuration']) && is_array($condition['configuration'])) {
        /** @var \Drupal\commerce\Plugin\Commerce\Condition\ConditionInterface $condition_instance */
        $condition_instance = $plugin_manager->createInstance($condition['plugin'], $condition['configuration']);
        if ($condition_instance instanceof ParentEntityAwareInterface) {
          $condition_instance->setParentEntity($this);
        }
        $conditions[] = $condition_instance;
      }
    }

    return $conditions;
  }

  /**
   * Sets the conditions.
   *
   * @param \Drupal\commerce\Plugin\Commerce\Condition\ConditionInterface[] $conditions
   *   The conditions.
   *
   * @return $this
   */
  public function setConditions(array $conditions): self {
    $this->conditions = [];
    foreach ($conditions as $condition) {
      $this->conditions[] = [
        'plugin' => $condition->getPluginId(),
        'configuration' => $condition->getConfiguration(),
      ];
    }

    return $this;
  }

  /**
   * Gets the condition operator.
   *
   * @return string
   *   The condition operator (AND or OR).
   */
  public function getConditionOperator(): string {
    return $this->condition_operator;
  }

  /**
   * Sets the condition operator.
   *
   * @param string $condition_operator
   *   The condition operator (AND or OR).
   *
   * @return $this
   */
  public function setConditionOperator(string $condition_operator): self {
    $this->condition_operator = $condition_operator;
    return $this;
  }

}

