declare(strict_types=1);

namespace Drupal\queue_manager\Drush\Commands;

use Composer\Console\Input\InputArgument;
use Drupal\Component\Plugin\Exception\PluginNotFoundException;
use Drupal\Core\Queue\QueueFactory;
use Drupal\Core\Queue\QueueWorkerInterface;
use Drupal\Core\Queue\QueueWorkerManagerInterface;
use Drupal\Core\Queue\SuspendQueueException;
use Drupal\queue_manager\Queue\Runner;
use Drush\Commands\AutowireTrait;
use Psr\Clock\ClockInterface;
use Psr\Log\LoggerInterface;
use Symfony\Component\Console\Attribute\AsCommand;
use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Input\InputOption;
use Symfony\Component\Console\Output\OutputInterface;

/**
 * {@selfdoc}
 */
#[AsCommand(
  name: 'qm:queue:run',
  description: 'Run a specific queue by name.',
)]
final class QueueRunCommand extends Command {

  use AutowireTrait;

  /**
   * Indicates that the command should stop.
   */
  private bool $stop = FALSE;

  /**
   * {@inheritdoc}
   */
  public function __construct(
    private readonly Runner $runner,
    private readonly QueueFactory $queueFactory,
    private readonly QueueWorkerManagerInterface $queueManager,
    private readonly ClockInterface $clock,
    private readonly LoggerInterface $logger,
  ) {
    parent::__construct();
  }

  /**
   * {@inheritdoc}
   */
  protected function configure(): void {
    $this
      ->addArgument(
        name: 'queue',
        mode: InputArgument::REQUIRED,
        description: 'The name of the queue to run.'
      )
      ->addOption(
        name: 'time-limit',
        mode: InputOption::VALUE_REQUIRED,
        description: 'The maximum number of seconds allocated for this command.',
        default: 365 * 24 * 3_600,
      )
      ->addOption(
        name: 'watch',
        mode: InputOption::VALUE_REQUIRED,
        description: 'Watch the queue continuously at the specified interval (seconds)',
      );
  }

  /**
   * {@inheritdoc}
   */
  protected function execute(InputInterface $input, OutputInterface $output): int {
    try {
      $time_limit = self::getTimeLimit($input);
      $watch = self::getWatchTimeout($input);
    }
    catch (\InvalidArgumentException $exception) {
      $this->logger->error($exception->getMessage(), ['exception' => $exception]);
      return self::FAILURE;
    }

    $queue_name = $input->getArgument('queue');
    \assert(\is_string($queue_name));
    try {
      $worker = $this->queueManager->createInstance($queue_name);
      \assert($worker instanceof QueueWorkerInterface);
    }
    catch (PluginNotFoundException $exception) {
      $this->logger->error(
        'There are no workers suitable for "{queue_name}" queue.',
        ['queue_name' => $queue_name, 'exception' => $exception],
      );
      return self::FAILURE;
    }

    $queue = $this->queueFactory->get($queue_name);
    $this->logger->info(
      'Started runner for "{queue_name}" queue.',
      ['queue_name' => $queue_name, 'total_items' => $queue->numberOfItems()],
    );

    $finish = $this->clock->now()->getTimestamp() + ($time_limit ?: 365 * 24 * 3_600);
    $count_down = fn (): float => (float) ($finish - $this->clock->now()->getTimestamp());
    $runner_time_limit = \max($time_limit / 100, 1);
    do {
      try {
        // @phpstan-ignore argument.type
        $this->runner->run($queue, $worker, (int) $runner_time_limit);
      }
      catch (SuspendQueueException $exception) {
        $this->logger->notice(
          'A worker for @queue queue suspended further processing of the queue.',
          ['@queue' => $worker->getPluginId(), 'exception' => $exception],
        );
        break;
      }

      if ($queue->numberOfItems() > 0) {
        continue;
      }
      if ($watch) {
        \usleep((int) (1_000_000 * $watch));
        continue;
      }
      break;
    } while ($count_down() > 0 && !$this->stop);

    $this->logger->info(
      'Stopped runner for "{queue_name}" queue.',
      ['queue_name' => $queue_name, 'total_items' => $queue->numberOfItems()],
    );
    return self::SUCCESS;
  }

  /**
   * @return positive-int
   */
  private static function getTimeLimit(InputInterface $input): int {
    // @phpstan-ignore cast.int
    $time_limit = (int) $input->getOption('time-limit');
    if ($time_limit <= 0) {
      throw new \InvalidArgumentException('Time limit must be a positive integer.');
    }
    return $time_limit;
  }

  /**
   * {@selfdoc}
   */
  private static function getWatchTimeout(InputInterface $input): ?float {
    $watch_timeout = $input->getOption('watch');
    if ($watch_timeout === NULL) {
      return NULL;
    }
    if (!\is_numeric($watch_timeout) || $watch_timeout <= 0) {
      throw new \InvalidArgumentException('Watch timeout must be a positive number.');
    }
    return (float) $watch_timeout;
  }

  /**
   * {@inheritdoc}
   */
  public function getSubscribedSignals(): array {
    return [\SIGTERM, \SIGQUIT, \SIGINT];
  }

  /**
   * {@inheritdoc}
   */
  public function handleSignal(int $signal, int|false $previousExitCode = 0): false|int {
    $this->stop = TRUE;
    return FALSE;
  }

}

